const b = $json.body || $json;
const from = String(b.from || b.whatsapp || '').trim();
const negocio = String(b.negocio || '').trim();
const nombre = String(b.nombre || '').trim();
const cuando = String(b.cuando || b.fecha || b.text || '').trim();
const citaId = `CITA-${Date.now()}`;
if (!from) return [{ json: { ok: false, error: 'falta from/whatsapp' } }];
return [{ json: {
  ok: true,
  sistema: '09-wasap-task-faq-citas',
  etapa: 'cita',
  citaId, from, negocio, nombre, cuando,
  estado: 'solicitada',
  reply: `Recibí tu pedido de cita${cuando ? ' (' + cuando + ')' : ''}. Te confirmamos en breve.`,
  status: 'draft_ready',
  todo: 'TODO: Sheet/Cal.com + aviso al negocio',
  at: new Date().toISOString()
}}];
